package com.bank.independent.pipeline;

import java.util.logging.Logger;

// Each service has its OWN pipeline. Deploying one triggers only its build.
public class DeploymentPipeline {
    private static final Logger log = Logger.getLogger(DeploymentPipeline.class.getName());
    private final String serviceName;

    public DeploymentPipeline(String serviceName) { this.serviceName = serviceName; }

    public void deploy(String version) {
        log.info(() -> "[" + serviceName + "] build + test");
        log.info(() -> "[" + serviceName + "] deploy version " + version
                     + " — no other service touched");
    }
}
