package com.bank.independent.contract;

import java.math.BigDecimal;

// Backward-compatible contract: the NEW optional 'reference' field.
// Old callers omit it (null) and still work during a rolling deploy.
public class PaymentRequest {
    private final String fromAccount;
    private final BigDecimal amount;
    private final String reference;   // NEW, optional — additive change

    public PaymentRequest(String fromAccount, BigDecimal amount, String reference) {
        this.fromAccount = fromAccount;
        this.amount = amount;
        this.reference = reference;   // may be null for old clients
    }
    public String getFromAccount() { return fromAccount; }
    public BigDecimal getAmount() { return amount; }
    public String getReference() { return reference; }
}
