package com.bank.independent.contract;

import java.util.logging.Logger;

// Accepts BOTH old requests (no reference) and new ones (with reference).
public class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());

    public String process(PaymentRequest req) {
        String ref = req.getReference() == null ? "AUTO-" + req.getFromAccount()
                                                 : req.getReference();
        log.info(() -> "Processing " + req.getAmount() + " from "
                     + req.getFromAccount() + " ref=" + ref);
        return "ACCEPTED ref=" + ref;
    }
}
