package com.bank.independent.shared;

import java.util.logging.Logger;

// A shared library that is versioned so services upgrade on THEIR schedule.
// If a change forces everyone to redeploy at once, that is LOCKSTEP (bad).
public class SharedContracts {
    private static final Logger log = Logger.getLogger(SharedContracts.class.getName());

    public static boolean isLockstepRequired(String oldVersion, String newVersion) {
        // Major version bump = breaking = forces coordinated redeploy.
        int oldMajor = Integer.parseInt(oldVersion.split("\\.")[0]);
        int newMajor = Integer.parseInt(newVersion.split("\\.")[0]);
        boolean lockstep = newMajor > oldMajor;
        if (lockstep) log.severe("LOCKSTEP: major bump forces all services to redeploy");
        else log.info("Compatible: services can upgrade independently");
        return lockstep;
    }
}
