package com.bank.independent;

import com.bank.independent.contract.PaymentRequest;
import com.bank.independent.contract.PaymentService;
import com.bank.independent.pipeline.DeploymentPipeline;
import com.bank.independent.shared.SharedContracts;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class IndependentDeployDemo {
    private static final Logger log = Logger.getLogger(IndependentDeployDemo.class.getName());

    public static void main(String[] args) {
        log.info("=== 1. Deploy Payment Service ALONE ===");
        new DeploymentPipeline("payment-service").deploy("2.3.0");

        log.info("=== 2. Backward-compatible contract (old + new clients) ===");
        PaymentService svc = new PaymentService();
        PaymentRequest oldClient = new PaymentRequest("SAV2001", new BigDecimal("50000"), null);
        PaymentRequest newClient = new PaymentRequest("SAV2001", new BigDecimal("50000"), "RENT-OCT");
        log.info("Old client: " + svc.process(oldClient));
        log.info("New client: " + svc.process(newClient));

        log.info("=== 3. Shared-library lockstep check ===");
        SharedContracts.isLockstepRequired("1.4.0", "1.5.0"); // compatible
        SharedContracts.isLockstepRequired("1.5.0", "2.0.0"); // lockstep!
    }
}
